    "seo_title_home": "TikTok 达人分析与视频下载工具",
    "seo_desc_home": "搜索并分析 TikTok 达人，涨粉与互动率排行一目了然；无水印下载视频、AI 脚本分析、标签生成，一个 Chrome 插件全搞定。",
    "seo_desc_price": "对比免费与付费套餐：视频下载、达人搜索、AI 脚本、数据导出等月度额度一览。免费注册即可开始，随时按需升级，解锁更多搜索与下载额度。",
    "seo_desc_download": "粘贴链接即可免费下载 TikTok 高清无水印视频，支持 MP3 音频与封面图。免登录、不保存文件；装插件还能在 TikTok 页面批量下载。",
    "seo_desc_script": "AI 把 TikTok 视频拆成结构化脚本：开头钩子、卖点、CTA 一目了然。分析爆款视频结构，几分钟生成你自己的带货文案。",
    "seo_desc_hashtag": "基于真实视频数据统计的 TikTok 高频标签，按关键词筛选、点击即可复制，帮你的下一条视频获得更多曝光，选题与发布更高效。",
    "seo_desc_nettest": "打不开 TikTok？一键检测当前网络能否访问 tiktok.com，并按提示排查地区限制与代理设置，让插件恢复正常工作。",
    "seo_desc_guide": "四步上手：安装 Chrome 或 Edge 插件、登录账号、浏览 TikTok、网页端协作。视频下载、达人数据、AI 脚本用法与常见问题全都有。",
    "seo_desc_kol_search": "按关键词或 ID 搜索 TikTok 达人，按国家、粉丝数、互动率精准筛选，查看涨粉与互动排行，一键收藏建立你自己的达人库。",
    "nf_title": "页面不存在",
    "nf_body": "你要找的页面不存在或已被移动。",
    "nf_back": "返回首页",
    "seo_desc_rank_kol": "TikTok 达人排行榜：按粉丝数、30 天涨粉、平均播放量与互动率多维排序，数据由插件实时采集计算，帮你快速锁定值得合作的优质达人。",
    "seo_desc_rank_video": "TikTok 视频排行榜：按播放量与点赞数排序，快速发现热门爆款视频，拆解高播放内容的共性，为选题和带货素材提供数据参考。",
    "seo_desc_rank_product": "TikTok 商品排行榜：按销量排序，发现 TikTok Shop 热卖商品，对比不同品类的销售表现，为选品和带货提供数据参考。",
