    "seo_title_home": "TikTok 達人分析與影片下載工具",
    "seo_desc_home": "搜尋並分析 TikTok 達人，漲粉與互動率排行一目了然；無浮水印下載影片、AI 腳本分析、標籤生成，一個擴充功能全搞定。",
    "seo_desc_price": "比較免費與付費方案：影片下載、達人搜尋、AI 腳本、資料匯出等每月額度一覽。免費註冊即可開始，隨時依需求升級，解鎖更多額度。",
    "seo_desc_download": "貼上連結即可免費下載 TikTok 高畫質無浮水印影片，支援 MP3 音訊與封面圖。免登入、不保存檔案；裝擴充功能還能批次下載。",
    "seo_desc_script": "AI 將 TikTok 影片拆成結構化腳本：開頭鉤子、賣點、CTA 一目了然。分析爆款影片結構，幾分鐘生成你自己的帶貨文案。",
    "seo_desc_hashtag": "基於真實影片資料統計的 TikTok 高頻標籤，可按關鍵字篩選、點擊即可複製，幫你的下一支影片獲得更多曝光，選題更有效率。",
    "seo_desc_nettest": "打不開 TikTok？一鍵檢測目前網路能否連上 tiktok.com，並依提示檢查地區限制與代理設定，讓擴充功能恢復正常運作。",
    "seo_desc_guide": "四步上手：安裝 Chrome 或 Edge 擴充功能、登入帳號、瀏覽 TikTok、網頁端協作。影片下載、達人數據、AI 腳本用法與常見問題全都有。",
    "seo_desc_kol_search": "依關鍵字或 ID 搜尋 TikTok 達人，按國家、粉絲數、互動率精準篩選，查看漲粉與互動排行，一鍵收藏建立你自己的達人名單。",
    "nf_title": "頁面不存在",
    "nf_body": "你要找的頁面不存在或已被移動。",
    "nf_back": "返回首頁",
    "seo_desc_rank_kol": "TikTok 達人排行榜：依粉絲數、30 天粉絲成長、平均觀看數與互動率排序，資料由擴充功能即時蒐集計算，協助你快速找到合適的合作達人。",
    "seo_desc_rank_video": "TikTok 影片排行榜：依觀看數與按讚數排序，快速發現熱門爆紅影片，拆解高觀看內容的共通點，作為選題與帶貨素材的參考。",
    "seo_desc_rank_product": "TikTok 商品排行榜：依銷量排序，發現 TikTok Shop 熱賣商品，比較不同品類的銷售表現，為選品與帶貨提供資料參考。",
    "hm_media_eyebrow": "產品宣傳片 · 18 秒預覽",
    "hm_media_play": "觀看完整產品宣傳片",
