    "seo_desc_rank_video": "TikTok動画ランキング。再生数といいね数で並び替えてバズ動画をすばやく発見。人気動画の傾向をつかみ、企画やコマース施策の参考に。",
    "seo_desc_rank_product": "TikTok商品ランキング。販売数で並び替えてTikTok Shopの売れ筋商品を発見。カテゴリごとの販売実績を比較しながら、商品選定の判断材料に。",
